            protected override bool CalcReadOnly() { return base.CalcReadOnly() || CalcReadOnly(Stan); }

            public void SetStan(StanObsługiProcesu stanProcesu) {
            using (ForceWriteMode()){
            baseStan = stanProcesu;

            if (Stan != StanObsługiProcesu.Wprowadzany)
            SetReadOnly(true);
            }
            }

            void SetStan(StanObsługiProcesu stanProcesu, WniosekDecyzja? decyzja, Date? dataDecyzji, Date? dataRealizacji){
            using (ForceWriteMode()) {
            baseStan = stanProcesu;

            if (decyzja!=null)
            baseDecyzja = (WniosekDecyzja)decyzja;

            if (dataDecyzji!=null)
            baseDataDecyzji = (Date)dataDecyzji;

            if (dataRealizacji!=null)
            baseDataRealizacji = (Date)dataRealizacji;

            if (Stan!=StanObsługiProcesu.Wprowadzany)
            SetReadOnly(true);
            }
            }

            protected override void OnLoaded() {
            base.OnLoaded();
            if ((AccessRight == AccessRights.ReadOnly || AccessRight == AccessRights.Granted) && HasToBeSetReadonly(Stan, Pars.Serwis))
            SetReadOnly(true);
            }

