//zmiana TK wcześniej sprawdzany był Kalendarz/Czas pracy a nie Norma czasu pracy
private void SprawdzCzyNieMaZaczytanegoGrafiku()
{
	Soneta.Web.Business.Workers.PracownikWebUserInfoWorker webInfo = new Soneta.Web.Business.Workers.PracownikWebUserInfoWorker();
	webInfo.Pracownik = Pracownik;
	
	var kalendarz = PobierzKalendarzPracownika();
	if (kalendarz == null)
		return;

	var dniKalendarza = Session.GetKalend()
		.DniKalendarza
		.WgKalendarz[kalendarz];
	
	var dzienPlanu = this.Pracownik.DniPlanu[WniosekDataOdbioru] as DzienPlanu;

	if (dzienPlanu != null)
	{
		if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
			throw new Exception(
				$"Nie można wskazać dnia {WniosekDataOdbioru} jako nowego dnia odbioru za święto, ponieważ w tym dniu występuje zaczytany grafik.");
		if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
			throw new Exception(
				$"It is not possible to indicate the day {WniosekDataOdbioru} as the new collection day for a holiday because there is a scheduled timetable on this day.");
	}
}


private void SprawdzStrefyPlanu()
{
	Date dataNowa = WniosekDataOdbioru;
	Date dataStara = GetPoprzedniaDataOdbioru();

	if (dataStara == Date.Empty)
		return;

	var kalendarz = PobierzKalendarzPracownika();
	if (kalendarz == null)
		return;

	var dniKalendarza = Session.GetKalend().DniKalendarza.WgKalendarz[kalendarz];

	//var dzienStary = this.Pracownik.DniPlanu[dataStara] as DzienPlanu ;// dniKalendarza.FirstOrDefault(x => x.Data == dataStara);
	//var dzienNowy = this.Pracownik.DniPlanu[dataNowa] as DzienPlanu;//dniKalendarza.FirstOrDefault(x => x.Data == dataNowa);
	
	//zmiana 25.06 TK - należy sprawdzać Czas pracy a nie plan pracy
	var dzienStary = this.Pracownik.DniPracy[dataStara] as DzienPracy;
	var dzienNowy = this.Pracownik.DniPracy[dataNowa] as DzienPracy;

	SprawdzNieobecnoscNaStarymDniu(dataStara);
	SprawdzNiedozwoloneStrefyNaStarymDniu(dzienStary, dataStara);

	SprawdzNieobecnoscNaNowymDniu(dataNowa);
	SprawdzNiedozwoloneStrefyNaNowymDniu(dzienNowy, dataNowa);
}

private void SprawdzNieobecnoscNaStarymDniu(Date data)
{
	Soneta.Web.Business.Workers.PracownikWebUserInfoWorker webInfo = new Soneta.Web.Business.Workers.PracownikWebUserInfoWorker();
	webInfo.Pracownik = Pracownik;
	
	if (!CzyJestNieobecnosc(Pracownik, data))
		return;
	
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
		throw new Exception(
			$"Nie można zmienić dnia odbioru za święto, ponieważ na dotychczasowym dniu odbioru ({data}) występuje nieobecność. " +
			"Zmianę należy przeprocesować osobnym zgłoszeniem.");
	
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
		throw new Exception(
			$"It is not possible to change the collection day for the holiday because there is an absence on the current collection day ({data}). " +
			"The change must be processed through a separate request.");	
}

private void SprawdzNieobecnoscNaNowymDniu(Date data)
{
	Soneta.Web.Business.Workers.PracownikWebUserInfoWorker webInfo = new Soneta.Web.Business.Workers.PracownikWebUserInfoWorker();
	webInfo.Pracownik = Pracownik;
	
	if (!CzyJestNieobecnosc(Pracownik, data))
		return;
	
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
		throw new Exception(
			$"W wybranym dniu odbioru ({data}) zarejestrowano nieobecność. Konieczność przeprocesowania wniosku indywidualnym zgłoszeniem.");
	
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
		throw new Exception(
			$"It is not possible to change the collection day for the holiday because there is an absence on the current collection day ({data}). " +
			"The change must be processed through a separate request.");
}

//private void SprawdzNiedozwoloneStrefyNaStarymDniu(DzienKalendarzaBase dzien, Date data)
private void SprawdzNiedozwoloneStrefyNaStarymDniu(DzienPracy dzien, Date data)
{
	Soneta.Web.Business.Workers.PracownikWebUserInfoWorker webInfo = new Soneta.Web.Business.Workers.PracownikWebUserInfoWorker();
	webInfo.Pracownik = Pracownik;
		
	if (dzien == null)
		return;

	var strefa = dzien.Strefy
		.FirstOrDefault(x => StrefyNiedozwoloneNaStarym.Contains(x.Definicja.Nazwa));

	if (strefa == null)
		return;
	
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
		throw new Exception(
			$"Nie można zmienić dnia odbioru za święto, ponieważ na dotychczasowym dniu odbioru ({data}) występuje strefa '{strefa.Definicja.Nazwa}'. " +
			"Zmianę należy przeprocesować osobnym zgłoszeniem.");
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
		throw new Exception(
			$"It is not possible to change the collection day for the holiday because the current collection day ({data}) falls within the '{strefa.Definicja.Nazwa}' zone. " +
			"The change must be processed through a separate request.");
}

//private void SprawdzNiedozwoloneStrefyNaNowymDniu(DzienKalendarzaBase dzien, Date data)
private void SprawdzNiedozwoloneStrefyNaNowymDniu(DzienPracy dzien, Date data)
{
	Soneta.Web.Business.Workers.PracownikWebUserInfoWorker webInfo = new Soneta.Web.Business.Workers.PracownikWebUserInfoWorker();
	webInfo.Pracownik = Pracownik;
	
	if (dzien == null)
		return;

	//var strefa = dzien.Strefy
	//	.FirstOrDefault(x => !StrefyDozwoloneNaNowym.Contains(x.Definicja.Nazwa));
	
	foreach(StrefaPracy strefa in dzien.Strefy)
	{
		if (strefa == null)
			return;
		if(!StrefyDozwoloneNaNowym.Contains(strefa.Definicja.Nazwa))
		{
			if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
				throw new Exception(
					$"Nie można wskazać dnia {data} jako nowego dnia odbioru za święto, ponieważ w tym dniu występuje '{strefa.Definicja.Nazwa}'. " +
					"Zmianę należy przeprocesować osobnym zgłoszeniem.");
			if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
					throw new Exception(
					$"It is not possible to indicate the day {data} as the new collection day for the holiday because the day falls zone '{strefa.Definicja.Nazwa}'. " +
					"The change must be processed through a separate request.");
		}
	}


}

private bool CzyJestNieobecnosc(Pracownik pracownik, Date data)
{
	return pracownik.Nieobecnosci.Any(x => x.Okres.Contains(data));
}

private Kalendarz PobierzKalendarzPracownika()
{
	return Pracownik[Date.Today].Etat?.Kalendarz;
}

private FromTo GetOkresRozliczeniowy()
{
	Soneta.Web.Business.Workers.PracownikWebUserInfoWorker webInfo = new Soneta.Web.Business.Workers.PracownikWebUserInfoWorker();
	webInfo.Pracownik = Pracownik;
	
	var kalendarz = PobierzKalendarzPracownika();

	// Kontrola na null musi wyprzedzać użycie - inaczej leci NullReferenceException
	// zamiast czytelnego komunikatu. PL jest wersją domyślną, żeby przy innej kulturze UI
	// walidacja nie została po cichu pominięta.
	if (kalendarz == null)
	{
		if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
			throw new Exception("It is not possible to establish the employee's calendar.");

		throw new Exception("Nie można ustalić kalendarza pracownika.");
	}

	var okres = kalendarz.WyliczOkresRoliczeniowyNadgodzin(WniosekDzienOdbierany);

	if (okres == FromTo.Empty)
	{
		if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
			throw new Exception("Error in calculating the settlement period.");

		throw new Exception("Błąd wyliczania okresu rozliczeniowego.");
	}

	return okres;
}

private void SprawdzOkresRozliczeniowy()
{
	Soneta.Web.Business.Workers.PracownikWebUserInfoWorker webInfo = new Soneta.Web.Business.Workers.PracownikWebUserInfoWorker();
	webInfo.Pracownik = Pracownik;
	
	var okres = GetOkresRozliczeniowy();

	if (okres.Contains(WniosekDataOdbioru))
		return;
	 
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
		throw new Exception(
			$"Nie można wskazać dnia odbioru {WniosekDataOdbioru}, ponieważ dzień odbioru musi znajdować się w okresie rozliczeniowym, " +
			$"w którym wypada święto, tj. od {okres.From} do {okres.To}.");
			 
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
		throw new Exception(
			$"The collection date {WniosekDataOdbioru} cannot be selected, " + 
			$"as the collection date must fall within the settlement period that includes the holiday, i.e., from {okres.From} to {okres.To}.");
}

private void SprawdzDataZatrudnienia()
{
	var dataZatrudnienia = Pracownik.Last.Etat?.Okres.From;
	var dataZwolnienia = Pracownik.Last.Etat?.Okres.To;
	Soneta.Web.Business.Workers.PracownikWebUserInfoWorker webInfo = new Soneta.Web.Business.Workers.PracownikWebUserInfoWorker();
	webInfo.Pracownik = Pracownik;

	if (dataZatrudnienia == null)
	{
		if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
			throw new Exception("Nie można ustalić daty zatrudnienia pracownika.");
	
		if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
			throw new Exception("It is not possible to determine the employee's employment date.");
	}


	if (dataZatrudnienia > WniosekDzienOdbierany)
	{
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
		throw new Exception(
			"Pracownik nie jest uprawniony do odbioru dnia wolnego, ponieważ został zatrudniony po święcie przypadającym w sobotę.");
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
		throw new Exception(
			"The employee is not entitled to take a day off because they were hired after the holiday falling on a Saturday.");
	}
	
	if (dataZwolnienia < WniosekDzienOdbierany)
	{
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
		throw new Exception(
			"Brak uprawnień do złożenia wniosku o odbiór dnia wolnego. Święto wypadające w sobotę jest poza okresem zatrudnienia.");
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
		throw new Exception(
			"No permission to submit a request for a day off. The holiday falling on a Saturday is outside the employment period.");
	}
	
	if (dataZwolnienia != Date.MaxValue && dataZwolnienia > WniosekDzienOdbierany)
	{
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CulturePL)
		throw new Exception(
			"Brak uprawnień do złożenia wniosku o odbiór dnia wolnego. Dzień odbioru dnia wolnego jest poza okresem zatrudnienia.");
	if(webInfo.UICulture == Soneta.Tools.CoreTools.CultureEN)
		throw new Exception(
		$"No permission to submit a request for a day off. The date of the compensatory day off falls outside the period of employment.");
	}
	
}

